-- Name: next_doc_no(text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.next_doc_no(p_prefix text, p_date date DEFAULT CURRENT_DATE) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE v_year int := extract(year FROM p_date); v_no int;
BEGIN
  ON CONFLICT (prefix, year) DO UPDATE SET last_no = doc_counters.last_no + 1
  RETURNING last_no INTO v_no;
  RETURN format('%s-%s-%s', p_prefix, v_year, lpad(v_no::text, 4, '0'));
END $$;


