--
-- TOC entry 252 (class 1259 OID 30692)
-- Name: v_boq_item_amounts; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_boq_item_amounts AS
 WITH linked AS (
         SELECT bi.id,
            sum(src.qty) AS linked_qty
           FROM ((public.boq_items bi
             JOIN public.product_qty_links l ON ((l.product_id = bi.product_id)))
             JOIN public.boq_items src ON (((src.boq_id = bi.boq_id) AND (src.product_id = l.source_product_id))))
          WHERE bi.qty_follows_links
          GROUP BY bi.id
        ), base AS (
         SELECT bi.id,
            bi.boq_id,
            bi.line,
            bi.brand_id,
            bi.product_id,
            bi.price_list_id,
            bi.is_custom,
            bi.is_edited,
            bi.group_name,
            bi.group_lines,
            bi.type_name,
            bi.type_lines,
            bi.description,
            bi.model,
            bi.unit,
            bi.specs,
            bi.cost,
            bi.cost_currency,
            bi.qty,
            bi.qty_follows_links,
            bi.profit_pct,
            bi.discount_pct,
            bi.default_profit_zero,
            bi.sort_order,
            bi.created_at,
            bi.updated_at,
            b.exchange_rate,
            b.selected_brand_id,
                CASE
                    WHEN bi.qty_follows_links THEN COALESCE(lk.linked_qty, (0)::numeric)
                    ELSE bi.qty
                END AS eff_qty,
            COALESCE(bi.profit_pct,
                CASE
                    WHEN bi.default_profit_zero THEN (0)::numeric
                    WHEN (bi.line = 'A'::bpchar) THEN b.imp_profit_pct
                    ELSE b.loc_profit_pct
                END) AS eff_profit_pct,
            COALESCE(bi.discount_pct,
                CASE
                    WHEN (bi.line = 'A'::bpchar) THEN b.imp_discount_pct
                    ELSE b.loc_discount_pct
                END) AS eff_discount_pct
           FROM ((public.boq_items bi
             JOIN public.boqs b ON ((b.id = bi.boq_id)))
             LEFT JOIN linked lk ON ((lk.id = bi.id)))
        ), priced AS (
         SELECT base.id,
            base.boq_id,
            base.line,
            base.brand_id,
            base.product_id,
            base.price_list_id,
            base.is_custom,
            base.is_edited,
            base.group_name,
            base.group_lines,
            base.type_name,
            base.type_lines,
            base.description,
            base.model,
            base.unit,
            base.specs,
            base.cost,
            base.cost_currency,
            base.qty,
            base.qty_follows_links,
            base.profit_pct,
            base.discount_pct,
            base.default_profit_zero,
            base.sort_order,
            base.created_at,
            base.updated_at,
            base.exchange_rate,
            base.selected_brand_id,
            base.eff_qty,
            base.eff_profit_pct,
            base.eff_discount_pct,
            round((round((COALESCE(base.cost, (0)::numeric) * ((1)::numeric + (base.eff_profit_pct / (100)::numeric))), 2) * ((1)::numeric - (base.eff_discount_pct / (100)::numeric))), 2) AS sell_rate,
            round((COALESCE(base.cost, (0)::numeric) * ((1)::numeric + (base.eff_profit_pct / (100)::numeric))), 2) AS list_rate
           FROM base
        )
 SELECT id,
    boq_id,
    line,
    brand_id,
    product_id,
    is_custom,
    sort_order,
    group_name,
    type_name,
    description,
    model,
    unit,
    cost,
    cost_currency,
    eff_qty AS qty,
    eff_profit_pct AS profit_pct,
    eff_discount_pct AS discount_pct,
    (cost IS NULL) AS missing_price,
    sell_rate AS rate,
        CASE
            WHEN (line = 'A'::bpchar) THEN round((sell_rate * exchange_rate), 2)
            ELSE sell_rate
        END AS rate_bdt,
        CASE
            WHEN (line = 'A'::bpchar) THEN (sell_rate * eff_qty)
            ELSE NULL::numeric
        END AS amount_usd,
        CASE
            WHEN (line = 'A'::bpchar) THEN (round((sell_rate * exchange_rate), 2) * eff_qty)
            ELSE (sell_rate * eff_qty)
        END AS amount_bdt,
        CASE
            WHEN (line = 'A'::bpchar) THEN ((COALESCE(cost, (0)::numeric) * eff_qty) * exchange_rate)
            ELSE (COALESCE(cost, (0)::numeric) * eff_qty)
        END AS cost_bdt,
        CASE
            WHEN (line = 'A'::bpchar) THEN (((list_rate - sell_rate) * eff_qty) * exchange_rate)
            ELSE ((list_rate - sell_rate) * eff_qty)
        END AS discount_bdt,
    ((line <> 'A'::bpchar) OR (brand_id = selected_brand_id)) AS counts_in_offer
   FROM priced p;


ALTER VIEW public.v_boq_item_amounts OWNER TO postgres;

--
-- TOC entry 5697 (class 0 OID 0)
-- Dependencies: 252
-- Name: VIEW v_boq_item_amounts; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.v_boq_item_amounts IS 'One row per BOQ line with the effective %, rate and amounts. Line A rows of other brands are kept for comparison but counts_in_offer = false.';


--
-- TOC entry 253 (class 1259 OID 30697)
-- Name: v_boq_brand_totals; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_boq_brand_totals AS
 SELECT boq_id,
    brand_id,
    count(*) FILTER (WHERE (qty > (0)::numeric)) AS items,
    sum(amount_bdt) AS imported_bdt,
    sum(amount_usd) AS imported_usd
   FROM public.v_boq_item_amounts
  WHERE (line = 'A'::bpchar)
  GROUP BY boq_id, brand_id;


ALTER VIEW public.v_boq_brand_totals OWNER TO postgres;

