    NULL::numeric AS total_b_bdt,
    NULL::numeric AS total_c_bdt,
    NULL::numeric AS ait_bdt,
    NULL::numeric AS vat_bdt,
    NULL::numeric AS grand_total_bdt,
    NULL::numeric AS usd_offer_ait_bdt,
    NULL::numeric AS usd_offer_vat_bdt,
    NULL::numeric AS usd_offer_taka_total,
    NULL::numeric AS cost_bdt,
    NULL::numeric AS discount_bdt,
    NULL::numeric AS profit_bdt;


ALTER VIEW public.v_boq_totals OWNER TO postgres;

