--
-- TOC entry 5643 (class 2618 OID 30704)
-- Name: v_boq_totals _RETURN; Type: RULE; Schema: public; Owner: postgres
--

CREATE OR REPLACE VIEW public.v_boq_totals AS
 WITH s AS (
         SELECT b.id AS boq_id,
            b.ait_pct,
            b.vat_pct,
            b.tax_method,
            b.tax_base_a,
            b.tax_base_b,
            b.tax_base_c,
            b.add_tax_to_total,
            COALESCE(sum(a.amount_bdt) FILTER (WHERE ((a.line = 'A'::bpchar) AND a.counts_in_offer)), (0)::numeric) AS a_bdt,
            COALESCE(sum(a.amount_usd) FILTER (WHERE ((a.line = 'A'::bpchar) AND a.counts_in_offer)), (0)::numeric) AS a_usd,
            COALESCE(sum(a.amount_bdt) FILTER (WHERE (a.line = 'B'::bpchar)), (0)::numeric) AS b_bdt,
            COALESCE(sum(a.amount_bdt) FILTER (WHERE (a.line = 'C'::bpchar)), (0)::numeric) AS c_bdt,
            COALESCE(sum(a.cost_bdt) FILTER (WHERE a.counts_in_offer), (0)::numeric) AS cost_bdt,
            COALESCE(sum(a.discount_bdt) FILTER (WHERE a.counts_in_offer), (0)::numeric) AS discount_bdt
           FROM (public.boqs b
             LEFT JOIN public.v_boq_item_amounts a ON ((a.boq_id = b.id)))
          GROUP BY b.id
        ), t AS (
         SELECT s.boq_id,
            s.ait_pct,
            s.vat_pct,
            s.tax_method,
            s.tax_base_a,
            s.tax_base_b,
            s.tax_base_c,
            s.add_tax_to_total,
            s.a_bdt,
            s.a_usd,
            s.b_bdt,
            s.c_bdt,
            s.cost_bdt,
            s.discount_bdt,
            ((
                CASE
                    WHEN s.tax_base_a THEN s.a_bdt
                    ELSE (0)::numeric
                END +
                CASE
                    WHEN s.tax_base_b THEN s.b_bdt
                    ELSE (0)::numeric
                END) +
                CASE
                    WHEN s.tax_base_c THEN s.c_bdt
                    ELSE (0)::numeric
                END) AS base_bdt,
            (
                CASE
                    WHEN s.tax_base_b THEN s.b_bdt
                    ELSE (0)::numeric
                END +
                CASE
                    WHEN s.tax_base_c THEN s.c_bdt
                    ELSE (0)::numeric
                END) AS base_usd_offer
           FROM s
        ), x AS (
         SELECT t.boq_id,
            t.ait_pct,
            t.vat_pct,
            t.tax_method,
            t.tax_base_a,
            t.tax_base_b,
            t.tax_base_c,
            t.add_tax_to_total,
            t.a_bdt,
            t.a_usd,
            t.b_bdt,
            t.c_bdt,
            t.cost_bdt,
            t.discount_bdt,
            t.base_bdt,
            t.base_usd_offer,
                CASE
                    WHEN (t.tax_method = 'gross'::text) THEN ((t.base_bdt * t.ait_pct) / ((100)::numeric - t.ait_pct))
                    ELSE ((t.base_bdt * t.ait_pct) / (100)::numeric)
                END AS ait_bdt,
                CASE
                    WHEN (t.tax_method = 'gross'::text) THEN ((t.base_usd_offer * t.ait_pct) / ((100)::numeric - t.ait_pct))
                    ELSE ((t.base_usd_offer * t.ait_pct) / (100)::numeric)
                END AS ait_usd_offer
           FROM t
        ), y AS (
         SELECT x.boq_id,
            x.ait_pct,
            x.vat_pct,
            x.tax_method,
            x.tax_base_a,
            x.tax_base_b,
            x.tax_base_c,
            x.add_tax_to_total,
            x.a_bdt,
            x.a_usd,
            x.b_bdt,
            x.c_bdt,
            x.cost_bdt,
            x.discount_bdt,
            x.base_bdt,
            x.base_usd_offer,
            x.ait_bdt,
            x.ait_usd_offer,
                CASE
                    WHEN (x.tax_method = 'gross'::text) THEN (((x.base_bdt + x.ait_bdt) * x.vat_pct) / ((100)::numeric - x.vat_pct))
                    ELSE (((x.base_bdt + x.ait_bdt) * x.vat_pct) / (100)::numeric)
                END AS vat_bdt,
                CASE
                    WHEN (x.tax_method = 'gross'::text) THEN (((x.base_usd_offer + x.ait_usd_offer) * x.vat_pct) / ((100)::numeric - x.vat_pct))
                    ELSE (((x.base_usd_offer + x.ait_usd_offer) * x.vat_pct) / (100)::numeric)
                END AS vat_usd_offer
           FROM x
        )
 SELECT boq_id,
    round(a_bdt, 2) AS total_a_bdt,
    round(a_usd, 2) AS total_a_usd,
    round(b_bdt, 2) AS total_b_bdt,
    round(c_bdt, 2) AS total_c_bdt,
    round(ait_bdt, 2) AS ait_bdt,
    round(vat_bdt, 2) AS vat_bdt,
    round((((a_bdt + b_bdt) + c_bdt) +
        CASE
            WHEN add_tax_to_total THEN (ait_bdt + vat_bdt)
            ELSE (0)::numeric
        END), 2) AS grand_total_bdt,
    round(ait_usd_offer, 2) AS usd_offer_ait_bdt,
    round(vat_usd_offer, 2) AS usd_offer_vat_bdt,
    round(((b_bdt + c_bdt) +
        CASE
            WHEN add_tax_to_total THEN (ait_usd_offer + vat_usd_offer)
            ELSE (0)::numeric
        END), 2) AS usd_offer_taka_total,
    round(cost_bdt, 2) AS cost_bdt,
    round(discount_bdt, 2) AS discount_bdt,
    round((((a_bdt + b_bdt) + c_bdt) - cost_bdt), 2) AS profit_bdt
   FROM y;


