INSERT INTO public.product_groups VALUES ('d2752fd4-36f5-5c59-9a76-8a2749622ca5', 'imported', 2, 'VRV A System Condensing Units (Outdoor unit)', '{"Variable Refrigerant Volume (VRV A) units having cooling capacities base on indoor temperature of 27°CDB, 19.5°WB and outdoor temp. of 35.0°CDB. Heating: Indoor temp. of 20°CDB, and outdoor temp. of 7°CDB, 6°CWB. Each unit shall be Modular type complete with DC Scroll Compressor, DX Condenser with Copper tube and Aluminum Fins. Condenser Fan with Fan guard, Y-shapped RefNet joints, complete in all respect. The unit shall operate when supplied with 400±10% V / 50hz / 3 Ph Electric power. The Condensing Units shall have Variable Frequency Drive Mechanism with necessary components.","The supply includes all accessories to complete VRV A mechanism."}', 1, '2026-11-05 13:58:33.937988+06', '2026-11-05 13:58:33.937988+06');
INSERT INTO public.product_groups VALUES ('ff6d4dc3-35df-57f3-856e-e65f4b9c1897', 'imported', 2, 'VRV A System Evaporating Units (Indoor Unit)', '{"Evaporating units having cooling capacities base on indoor temperature of 27°CDB, 19.5°WB and outdoor temp. of 35.0°CDB. Heating: Indoor temp. of 20°CDB, and outdoor temp. of 7°CDB, 6°CWB. Each unit shall be operated with Variable refrigerant Volume (VRV A) outdoor units. Evaporating Units shall have refrigerant control valve (EXV) washable filter, fan speed controller etc. complete in all respect. Vent port shall be built in inside the unit. The unit shall operate when supplied with 220±10% V / 50hz / 1 Ph Electric power."}', 2, '2026-11-05 13:58:33.937988+06', '2026-11-05 13:58:33.937988+06');
INSERT INTO public.product_groups VALUES ('6ced5b71-5b59-595a-87c3-186349416674', 'imported', 2, 'Centralised Control Systems', '{"The user-friendly controller already features colors, multilingual function, and icons in the display for ease of understanding; now, further convenience has been added. New communication capabilities enable centralized control via a Web browser and the sending of e-mail alerts on system operation. A wide variety of control methods can be accommodated, permitting administrators to monitor and operate the system even when they are away from the controller."}', 3, '2026-11-05 13:58:33.937988+06', '2026-11-05 13:58:33.937988+06');
INSERT INTO public.product_groups VALUES ('55f36b54-ff04-5f91-ab4f-c8b9f36ac799', 'imported', 2, 'Ref Net (Distributor / Y-pipe / Branch pipe)', '{"The REFNET joint both reduces the amount of work involved in installation and increases the reliability of the system."}', 4, '2026-11-05 13:58:33.937988+06', '2026-11-05 13:58:33.937988+06');
INSERT INTO public.product_groups VALUES ('53b87fe3-66ec-5811-a051-b36fb144dfc4', 'imported', 2, 'Freight', '{}', 5, '2026-11-05 13:58:33.937988+06', '2026-11-05 13:58:33.937988+06');
INSERT INTO public.product_groups VALUES ('e9dc50b7-c15b-536b-bba1-90de5ec82b6a', 'imported', 3, 'VRF System Condensing Units (Out door unit)', '{"Variable Refrigerant Flow (VRF) units having cooling capacities as mentioned below when air entering the coil at 780 DB / 66.50F WB. And leaving the coil at 550F DB 54.60F WB. Each unit shall be Modular Type complete with Multi Digital Scroll Compressor, DX Condenser with Copper tube and Aluminum Fins. Condenser Fan with Fan guard, Y-shaped RefNet joints, complete in all respect. The unit shall operate when supplied with 400±10% V / 50hz / 3 Ph Electric power. The Condensing Units shall have Variable Frequency Drive Mechanism with necessary components.","The supply includes all accessories to complete VRF mechanism."}', 1, '2026-11-05 13:58:33.937988+06', '2026-11-05 13:58:33.937988+06');
INSERT INTO public.product_groups VALUES ('f6272d73-11aa-524e-a7db-1e41a718e61f', 'imported', 3, 'VRF System Evaporating Units (Indoor Unit)', '{"Evaporating units having cooling capacities as mentioned below when air entering the coil at 780 DB / 66.50F WB. And leaving the coil at 550F DB 54.60F WB. Each unit shall be operated with Variable refrigerant Flow (VRF) outdoor units. Evaporating Units shall have refrigerant control valve (EXV) washable filter, fan speed controller etc. complete in all respect. Vent port shall be built in inside the unit. The unit shall operate when supplied with 220±10% V / 50hz / 1 Ph Electric power."}', 2, '2026-11-05 13:58:33.937988+06', '2026-11-05 13:58:33.937988+06');
INSERT INTO public.product_groups VALUES ('d35c3458-0ec1-5274-8142-aecb3f3819d4', 'imported', 3, 'Remote Controller', '{}', 3, '2026-11-05 13:58:33.937988+06', '2026-11-05 13:58:33.937988+06');
INSERT INTO public.product_groups VALUES ('85ce6d95-76f0-5523-bb2d-8fea1edd10ce', 'imported', 3, 'Centralized control system', '{"The user-friendly controller already features colors, multilingual function, and icons in the display for ease of understanding; now, further convenience has been added. A wide variety of control methods can be accommodated, permitting administrators to monitor and operate the system even when they are away from the controller."}', 4, '2026-11-05 13:58:33.937988+06', '2026-11-05 13:58:33.937988+06');
